import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.DeW-aKVm.js";const m=JSON.parse(`{"title":"Documentation for coding agents","description":"A compact map of Nirantara's documentation, plus the details that are easiest to get wrong when generating configuration for k3sctl, the MCP servers, or the omniroute-operator.","frontmatter":{"title":"Documentation for coding agents","description":"A compact map of Nirantara's documentation, plus the details that are easiest to get wrong when generating configuration for k3sctl, the MCP servers, or the omniroute-operator.","outline":"deep"},"headers":[],"relativePath":"agents.md","filePath":"agents.md"}`),i={name:"agents.md"};function s(l,e,c,n,d,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="documentation-for-coding-agents" tabindex="-1">Documentation for coding agents <a class="header-anchor" href="#documentation-for-coding-agents" aria-label="Permalink to &quot;Documentation for coding agents&quot;">​</a></h1><p>Nirantara maintains four open-source projects. The documentation below is organised per project, and every page is also available as raw Markdown by appending <code>.md</code> to its URL. The curated index is at <a href="/llms.txt">/llms.txt</a> and the full corpus at <a href="/llms-full.txt">/llms-full.txt</a>.</p><h2 id="where-to-look" tabindex="-1">Where to look <a class="header-anchor" href="#where-to-look" aria-label="Permalink to &quot;Where to look&quot;">​</a></h2><h3 id="k3sctl" tabindex="-1">k3sctl <a class="header-anchor" href="#k3sctl" aria-label="Permalink to &quot;k3sctl&quot;">​</a></h3><p>Declarative K3s cluster lifecycle over SSH.</p><ul><li><a href="./docs/k3sctl/">Overview</a></li><li><a href="./docs/k3sctl/installation">Installation</a></li><li><a href="./docs/k3sctl/configuration">Configuration</a>: the <code>Cluster</code> file, hosts, K3s settings, and drain options.</li><li><a href="./docs/k3sctl/commands">Commands</a>: <code>apply</code>, <code>reset</code>, <code>kubeconfig</code>, <code>backup</code>, and the flags each accepts.</li></ul><h3 id="mssql-mcp-go" tabindex="-1">mssql-mcp-go <a class="header-anchor" href="#mssql-mcp-go" aria-label="Permalink to &quot;mssql-mcp-go&quot;">​</a></h3><p>Read-only MCP server for Microsoft SQL Server.</p><ul><li><a href="./docs/mssql-mcp-go/">Overview</a></li><li><a href="./docs/mssql-mcp-go/installation">Installation</a></li><li><a href="./docs/mssql-mcp-go/configuration">Configuration</a>: <code>config.yaml</code>, <code>SQLSERVER_*</code> variables, and client snippets.</li><li><a href="./docs/mssql-mcp-go/tools">Tools</a></li></ul><h3 id="postgres-mcp-go" tabindex="-1">postgres-mcp-go <a class="header-anchor" href="#postgres-mcp-go" aria-label="Permalink to &quot;postgres-mcp-go&quot;">​</a></h3><p>Read-only MCP server for PostgreSQL.</p><ul><li><a href="./docs/postgres-mcp-go/">Overview</a></li><li><a href="./docs/postgres-mcp-go/installation">Installation</a></li><li><a href="./docs/postgres-mcp-go/configuration">Configuration</a>: <code>config.yaml</code>, <code>POSTGRES_*</code> variables, and client snippets.</li><li><a href="./docs/postgres-mcp-go/tools">Tools</a></li></ul><h3 id="omniroute-operator" tabindex="-1">omniroute-operator <a class="header-anchor" href="#omniroute-operator" aria-label="Permalink to &quot;omniroute-operator&quot;">​</a></h3><p>Kubernetes operator for OmniRoute.</p><ul><li><a href="./docs/omniroute-operator/">Overview</a></li><li><a href="./docs/omniroute-operator/installation">Installation</a></li><li><a href="./docs/omniroute-operator/omniroute-cr">OmniRoute CR</a>: every field in <code>gateway.omniroute.ai/v1alpha1</code>.</li><li><a href="./docs/omniroute-operator/local-development">Local development</a></li></ul><h2 id="details-that-are-easy-to-get-wrong" tabindex="-1">Details that are easy to get wrong <a class="header-anchor" href="#details-that-are-easy-to-get-wrong" aria-label="Permalink to &quot;Details that are easy to get wrong&quot;">​</a></h2><h3 id="k3sctl-1" tabindex="-1">k3sctl <a class="header-anchor" href="#k3sctl-1" aria-label="Permalink to &quot;k3sctl&quot;">​</a></h3><ol><li>Hosts must be Linux. <code>k3sctl</code> installs K3s and systemd units over SSH.</li><li>The configuration is <code>apiVersion: k3sctl.k3sproject.io/v1beta1</code>, <code>kind: Cluster</code>.</li><li><code>spec.hosts[]</code> entries choose a <code>role</code> of <code>server</code> or <code>agent</code>. Servers are the default.</li><li>Extra YAML documents in the same file are applied after installation with <code>kubectl apply</code>. Separate them with <code>---</code>, and make each one a valid Kubernetes manifest.</li><li><code>apply</code> is idempotent and only changes what drifted. <code>--dry-run</code> shows the plan without changing the cluster.</li><li><code>reset</code> removes K3s from the hosts. It is not the same as deleting a namespace.</li></ol><h3 id="mcp-servers" tabindex="-1">MCP servers <a class="header-anchor" href="#mcp-servers" aria-label="Permalink to &quot;MCP servers&quot;">​</a></h3><ol><li>Both servers are read-only. Mutating SQL is rejected before execution, and stored procedures are analysed, never run.</li><li>Environment variables override <code>config.yaml</code>; never assume the file wins.</li><li>The default transport is <code>stdio</code>, so an MCP client launches the binary rather than connecting to a port.</li><li><code>mssql-mcp-go</code> uses <code>SQLSERVER_*</code> variables and <code>encrypt</code>/<code>ssl</code> options that are SQL Server specific. <code>postgres-mcp-go</code> uses <code>POSTGRES_*</code> variables and <code>ssl_mode</code> plus <code>search_path</code>.</li><li>The tool names and groups are the same across both servers, but the SQL dialect differs. Do not copy a T-SQL snippet into a PostgreSQL answer.</li></ol><h3 id="omniroute-operator-1" tabindex="-1">omniroute-operator <a class="header-anchor" href="#omniroute-operator-1" aria-label="Permalink to &quot;omniroute-operator&quot;">​</a></h3><ol><li>The group and version are <code>gateway.omniroute.ai/v1alpha1</code>; the kind is <code>OmniRoute</code>.</li><li><code>spec.replicas</code> is effectively capped at <code>1</code> because OmniRoute stores state in SQLite with a single writer.</li><li>Credentials come from an existing Secret with <code>JWT_SECRET</code>, <code>API_KEY_SECRET</code>, and <code>INITIAL_PASSWORD</code>.</li><li><code>spec.ingress.enabled</code> defaults to <code>false</code>. Enable it explicitly and set <code>className</code>, <code>host</code>, and TLS if the instance must be public.</li><li><code>spec.persistence.enabled</code> creates a PVC. Disabling it makes the instance ephemeral.</li><li><code>NODE_OPTIONS</code> is derived from the memory limit; do not hardcode it in <code>spec.env</code> unless you need to override the derived value.</li></ol>',22)])])}const u=o(i,[["render",s]]);export{m as __pageData,u as default};
